    deleteAccountSession: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description Session id (UUID v4) from `SessionInfo.id`. */
                id: string;
            };
            cookie?: {
                /**
                 * @description Dashboard session cookie. Sealed; opaque to the client
                 *     (`HttpOnly; Secure; SameSite=Lax`). 7-day fixed lifetime.
                 *     The browser sets it automatically on `/login` / `/signup`;
                 *     the SDK uses the device-code flow instead and never sets
                 *     this cookie.
                 */
                faas_sid?: components["parameters"]["CookieSession"];
            };
        };
        requestBody: {
            content: {
                "application/json": {
                    csrf_token: string;
                };
            };
        };
        responses: {
            /** @description Session revoked. `Set-Cookie: faas_sid=…` clears the cookie if the path id matched the current session. */
            204: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /**
             * @description CSRF check failed (`csrf_mismatch`) or the path id
             *     is not a valid UUID (`validation_failed`).
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description See `/v1/auth/logout`. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /**
             * @description No active session matches the id on this account
             *     (does not exist, already revoked, or belongs to
             *     another account). The 404 is the same shape
             *     regardless — we never leak existence across
             *     accounts.
             */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            429: components["responses"]["TooManyRequests"];
        };
    };
